// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Original value and datatype assertions for the 2024 numeric productions. The supplied gql-compat GL01-GL10 and
 * digit-group-separator cases identify the syntax families; these cases additionally distinguish exactness, precision,
 * token boundaries, and bounded materialization.
 */
class GqlNumericLiteralTest {

	private SailRepository repository;

	private RepositoryConnection connection;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		connection = repository.getConnection();
	}

	@AfterEach
	void tearDown() {
		connection.close();
		repository.shutDown();
	}

	@Test
	void decimalDigitSeparatorsPreserveExactValues() {
		integer("123_456_789_012_345_678_901", "123456789012345678901");
		decimal("1_234.50_00", "1234.5000");
		decimal(".00_125", "0.00125");
		decimal("9_007_199_254_740_993.0", "9007199254740993.0");
	}

	@Test
	void radixLiteralsPreserveArbitraryPrecisionAndHexSuffixDigits() {
		integer("0xDEAD", "57005");
		integer("0xdead", "57005");
		integer("0x_F_F", "255");
		integer("0o_7_7", "63");
		integer("0b_1010_0101", "165");
		integer("0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF", "340282366920938463463374607431768211455");
		integer("-0xFF", "-255");
		integer("0xF + 0o7 + 0b1", "23");
	}

	@Test
	void exactSuffixPreservesDecimalValuesWithoutBinaryRounding() {
		decimal("9_007_199_254_740_993M", "9007199254740993");
		decimal("9.007199254740993e15M", "9007199254740993");
		decimal("1_25E-2m", "1.25");
		decimal(".1M + .2M", "0.3");
		decimal("1.M", "1");
		decimal(".00_125m", "0.00125");
	}

	@Test
	void floatSuffixActuallyUsesSinglePrecision() {
		Literal value = value("16_777_217F");
		assertEquals(XSD.FLOAT, value.getDatatype());
		assertEquals(16_777_216F, value.floatValue());
		value = value("1.25e+2f");
		assertEquals(XSD.FLOAT, value.getDatatype());
		assertEquals(125F, value.floatValue());
	}

	@Test
	void doubleSuffixAndUnsuffixedExponentUseDoublePrecision() {
		for (String expression : List.of("16_777_217D", "1.6777217e7d", "1.6777217E+0_7")) {
			Literal value = value(expression);
			assertEquals(XSD.DOUBLE, value.getDatatype(), expression);
			assertEquals(16_777_217D, value.doubleValue(), expression);
		}
	}

	@Test
	void omittedDecimalDigitsComposeWithExponentsAndSuffixes() {
		decimal("1.", "1");
		decimal(".5E+2M", "50");
		decimal("1.E-2m", "0.01");
		for (String expression : List.of(".5F", "1.F", ".5D", "1.D", "1.e+2F", ".5e-2D")) {
			Literal value = value(expression);
			assertEquals(expression.endsWith("F") ? XSD.FLOAT : XSD.DOUBLE, value.getDatatype(), expression);
		}
		assertEquals(0.5F, value(".5F").floatValue());
		assertEquals(1F, value("1.F").floatValue());
		assertEquals(0.5D, value(".5D").doubleValue());
		assertEquals(1D, value("1.D").doubleValue());
		assertEquals(100F, value("1.e+2F").floatValue());
		assertEquals(0.005D, value(".5e-2D").doubleValue());
	}

	@Test
	void numericTokensRetainTheirSourceSpellingAndOffsets() {
		String source = "  0xDEAD 1_000 .5M 1e+2D";
		List<GqlLexer.Token> tokens = GqlLexer.tokenize(source);
		List<String> spellings = List.of("0xDEAD", "1_000", ".5M", "1e+2D");
		assertEquals(spellings.size() + 1, tokens.size());
		for (int i = 0; i < spellings.size(); i++) {
			assertEquals(GqlLexer.Kind.NUMBER, tokens.get(i).kind());
			assertEquals(spellings.get(i), tokens.get(i).text());
			assertEquals(source.indexOf(spellings.get(i)), tokens.get(i).offset());
		}
	}

	@Test
	void numericSyntaxRejectsInvalidSeparatorsRadixDigitsAndSuffixes() {
		for (String invalid : List.of("1_", "1__0", "1_.0", "1._0", ".1_", "1e_2", "1e+_2", "1e2_",
				"0x", "0x_", "0x__FF", "0xFF_", "0xFG", "0o8", "0b2", "0b1F", "0o7M", "0xFFM",
				"1MM", "1.0DD", "1e2Ffoo", "0x1.0", "0X10", "0B10", "0O10")) {
			assertThrows(MalformedQueryException.class,
					() -> connection.prepareTupleQuery(QueryLanguage.GQL, "RETURN " + invalid + " AS value"), invalid);
		}
	}

	@Test
	void approximateOverflowIsRejectedWithoutRejectingFiniteBoundaries() {
		assertEquals(Float.MAX_VALUE, value("3.4028235e38F").floatValue());
		assertEquals(Double.MAX_VALUE, value("1.7976931348623157e308D").doubleValue());
		assertEquals(-Float.MAX_VALUE, value("-3.4028235e38F").floatValue());
		assertEquals(-Double.MAX_VALUE, value("-1.7976931348623157e308D").doubleValue());
		for (String expression : List.of("3.5e38F", "1e309D", "1e309", "-3.5e38F", "-1e309D", "-1e309")) {
			assertThrows(MalformedQueryException.class,
					() -> connection.prepareTupleQuery(QueryLanguage.GQL, "RETURN " + expression + " AS value"),
					expression);
		}
	}

	@Test
	void exactExponentExpansionRemainsBoundedBeforeCreatingRdfLiteral() {
		decimal("1E4095M", "1E4095");
		decimal("1E-4094M", "1E-4094");
		for (String expression : List.of("1E4096M", "1E-4095M", "1E2147483647M", "1E-2147483647M")) {
			assertThrows(MalformedQueryException.class,
					() -> connection.prepareTupleQuery(QueryLanguage.GQL, "RETURN " + expression + " AS value"),
					expression);
		}
	}

	@Test
	void sourceLengthIsBoundedBeforeRemovingDigitSeparators() {
		String boundary = "7".repeat(4096);
		integer(boundary, boundary);
		for (String expression : List.of(boundary + "7", "0_".repeat(2048) + "1")) {
			assertThrows(MalformedQueryException.class,
					() -> connection.prepareTupleQuery(QueryLanguage.GQL, "RETURN " + expression + " AS value"));
		}
	}

	private void integer(String expression, String expected) {
		Literal value = value(expression);
		assertEquals(XSD.INTEGER, value.getDatatype(), expression);
		assertEquals(new BigInteger(expected), value.integerValue(), expression);
	}

	private void decimal(String expression, String expected) {
		Literal value = value(expression);
		assertEquals(XSD.DECIMAL, value.getDatatype(), expression);
		assertEquals(0, new BigDecimal(expected).compareTo(value.decimalValue()), expression);
	}

	private Literal value(String expression) {
		try (TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.GQL,
				"RETURN " + expression + " AS value").evaluate()) {
			assertTrue(result.hasNext(), expression);
			Literal value = (Literal) result.next().getValue("value");
			assertFalse(result.hasNext(), expression);
			return value;
		}
	}
}
